You are building a wrapper for the Infigraph CLI to satisfy issue #597.

Create a new file `scripts/analysis/infigraph.py` that contains an `InfigraphRuntime` class. It must be able to invoke a given executable (e.g. `infigraph capabilities --format=json`), parse the output, and return a `CapabilityReport`.

The wrapper defines normalized statuses for `analysis_complete`, `analysis_unavailable`, and `analysis_failed`, including actionable failure reasons. The selected Infigraph release and resolution metadata (version, resolved_path, checksum) must be recorded reproducibly.

Example Implementation for `scripts/analysis/infigraph.py`:

```python
import json
import subprocess
from dataclasses import dataclass
from typing import Literal

@dataclass(frozen=True)
class InfigraphMetadata:
    version: str
    resolved_path: str
    checksum: str

@dataclass(frozen=True)
class CapabilityReport:
    status: Literal["analysis_complete", "analysis_unavailable", "analysis_failed"]
    reason: str
    metadata: InfigraphMetadata | None = None

class InfigraphRuntime:
    def __init__(self, executable_path: str = "infigraph"):
        self.executable_path = executable_path

    def check_capabilities(self, timeout: float = 5.0) -> CapabilityReport:
        try:
            result = subprocess.run(
                [self.executable_path, "capabilities", "--format=json"],
                capture_output=True,
                text=True,
                timeout=timeout,
                check=True
            )
            data = json.loads(result.stdout)

            metadata = InfigraphMetadata(
                version=data.get("version", "unknown"),
                resolved_path=self.executable_path,
                checksum=data.get("checksum", "unknown")
            )

            if data.get("ready_for_analysis") is True:
                return CapabilityReport(
                    status="analysis_complete",
                    reason="Capabilities are fully supported and ready.",
                    metadata=metadata
                )
            else:
                return CapabilityReport(
                    status="analysis_unavailable",
                    reason="Executable found but required capabilities are missing.",
                    metadata=metadata
                )

        except FileNotFoundError:
            return CapabilityReport(
                status="analysis_unavailable",
                reason=f"Executable '{self.executable_path}' not found."
            )
        except subprocess.TimeoutExpired:
            # SECURITY: Do not leak exception context
            return CapabilityReport(
                status="analysis_failed",
                reason="Command timed out while checking capabilities."
            )
        except subprocess.CalledProcessError as e:
            return CapabilityReport(
                status="analysis_failed",
                reason=f"Command failed with exit code {e.returncode}."
            )
        except json.JSONDecodeError:
            return CapabilityReport(
                status="analysis_failed",
                reason="Malformed JSON output from executable."
            )
```

